{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "Pentazocine, the closest analogue (Morgan 0.2817), has an absolute oral bioavailability of 18% in healthy subjects after tablet dosing, below the 20% threshold; it shares the N-prenyl tertiary amine and lipophilic fused-ring scaffold with the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "8-Prenylnaringenin shows low oral bioavailability in humans with large inter-individual variation, supporting the metabolic/absorption liability of the prenyl motif.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Tocotrienol-rich palm oil has poor oral bioavailability in humans, consistent with highly lipophilic prenylated molecules facing absorption or first-pass limitations.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "6-Prenylnaringenin also shows low oral bioavailability in humans, reinforcing the low-F pattern for prenylated lipophilic compounds.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "MK-458, a lipophilic fused-ring tertiary amine, has an absolute oral bioavailability of about 5% in patients, demonstrating that such scaffolds can undergo extensive first-pass elimination.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Doravirine, a fused heterocycle with a chloro-substituted aryl and carboxamide, has an absolute oral bioavailability of about 64%, showing that some fused heterocycles can be well absorbed.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C17"],
      "claim": "Balovaptan, a chloro-substituted fused heterocycle, is BCS class I-like with 100% oral bioavailability, but it is considerably more polar and soluble than the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C08"],
      "claim": "Several 5-HT3 antagonists with chloro-substituted fused heterocycles have oral bioavailability of 50-80%, indicating high F is possible for related heterocyclic scaffolds.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C24"],
      "claim": "Dolutegravir, a fused heterocyclic integrase inhibitor, has an estimated F of 74.6%, but it is more polar and lacks the prenyl/thiourea combination present in the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C01"],
      "claim": "Loratadine has good oral bioavailability in healthy volunteers, but this is not an absolute F measurement and its tricyclic chloro scaffold differs from the query's thiourea/prenyl system.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "low",
  "decision_summary": "The most transferable experimental evidence points to low oral bioavailability: the closest analogue pentazocine has absolute F=18% in healthy humans, and several prenylated lipophilic molecules show low or poor oral bioavailability. High-F analogues are structurally more polar/soluble and have lower transferability, so the balance favors F<20% despite uncertainty.",
  "evidence_gaps": [
    "No experimental bioavailability data exist for the query molecule itself.",
    "All analogues have low Morgan similarity (<0.3), limiting transferability.",
    "Pentazocine F=18% is close to the 20% threshold; small structural differences could shift the outcome.",
    "No direct data on query solubility, permeability, or first-pass metabolism; thiourea and prenyl metabolic liabilities are inferred.",
    "High-F analogues are more polar/soluble and lack the prenyl/thiourea combination, so their relevance is uncertain."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

